<title>BIEK Computer Science 12th Class Past Paper Analysis (2015-2025)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a5276;
    --primary-light: #2980b9;
    --secondary: #148f77;
    --secondary-light: #1abc9c;
    --accent: #e67e22;
    --accent-light: #f39c12;
    --bg: #f8f9fa;
    --card-bg: #ffffff;
    --text: #2c3e50;
    --text-light: #5d6d7e;
    --border: #dce1e6;
    --mcq-color: #2980b9;
    --short-color: #27ae60;
    --long-color: #e67e22;
    --total-color: #8e44ad;
  }
  * { margin:0; padding:0; box-sizing:border-box; }
  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.65;
  }
  .container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }

  /* Header */
  .report-header {
    background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
    color: #fff;
    padding: 56px 0 48px;
    margin-bottom: 40px;
  }
  .report-header h1 { font-size: 2rem; font-weight: 700; margin-bottom: 8px; }
  .report-header .subtitle { font-size: 1.1rem; opacity: .88; font-weight: 400; }
  .report-header .meta { margin-top: 18px; font-size: .88rem; opacity: .72; }

  /* Sections */
  section { margin-bottom: 48px; }
  section h2 {
    font-size: 1.45rem;
    color: var(--primary);
    border-bottom: 3px solid var(--secondary-light);
    padding-bottom: 8px;
    margin-bottom: 20px;
  }
  section h3 {
    font-size: 1.15rem;
    color: var(--primary-light);
    margin: 22px 0 10px;
  }

  /* Cards */
  .card {
    background: var(--card-bg);
    border-radius: 8px;
    box-shadow: 0 1px 4px rgba(0,0,0,.08);
    padding: 24px;
    margin-bottom: 20px;
  }
  .kpi-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
  }
  .kpi-card {
    background: var(--card-bg);
    border-radius: 8px;
    box-shadow: 0 1px 4px rgba(0,0,0,.08);
    padding: 20px;
    text-align: center;
    border-top: 4px solid var(--primary-light);
  }
  .kpi-card.alt { border-top-color: var(--secondary); }
  .kpi-card.warn { border-top-color: var(--accent); }
  .kpi-card .kpi-value { font-size: 2rem; font-weight: 700; color: var(--primary); }
  .kpi-card .kpi-label { font-size: .85rem; color: var(--text-light); margin-top: 4px; }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: .92rem;
    margin: 12px 0 20px;
  }
  th, td { padding: 10px 14px; text-align: center; border-bottom: 1px solid var(--border); }
  th { background: var(--primary); color: #fff; font-weight: 600; }
  tr:nth-child(even) { background: #f4f6f8; }
  tr:hover { background: #eaf2f8; }
  td:first-child, th:first-child { text-align: left; font-weight: 600; }

  /* Chart containers */
  .chart-wrap {
    position: relative;
    width: 100%;
    max-width: 900px;
    margin: 16px auto;
  }
  .chart-wrap.half {
    display: inline-block;
    width: 48%;
    vertical-align: top;
  }

  /* Topic bars */
  .topic-bar-row {
    display: flex;
    align-items: center;
    margin-bottom: 8px;
  }
  .topic-bar-label {
    width: 220px;
    font-size: .88rem;
    text-align: right;
    padding-right: 12px;
    color: var(--text);
    flex-shrink: 0;
  }
  .topic-bar-track {
    flex: 1;
    background: #ecf0f1;
    border-radius: 4px;
    height: 22px;
    position: relative;
  }
  .topic-bar-fill {
    height: 100%;
    border-radius: 4px;
    transition: width .4s ease;
  }
  .topic-bar-count {
    position: absolute;
    right: 8px;
    top: 2px;
    font-size: .78rem;
    font-weight: 600;
    color: #fff;
    text-shadow: 0 1px 2px rgba(0,0,0,.3);
  }

  /* Insight callouts */
  .insight {
    background: #eafaf1;
    border-left: 4px solid var(--secondary);
    padding: 14px 18px;
    border-radius: 0 6px 6px 0;
    margin: 14px 0;
    font-size: .93rem;
  }
  .insight.warn { background: #fef9e7; border-left-color: var(--accent); }
  .insight.info { background: #eaf2f8; border-left-color: var(--primary-light); }

  /* Tag */
  .tag {
    display: inline-block;
    padding: 3px 10px;
    border-radius: 12px;
    font-size: .78rem;
    font-weight: 600;
    margin: 2px 3px;
  }
  .tag.mcq { background: #d6eaf8; color: #21618c; }
  .tag.short { background: #d5f5e3; color: #1e8449; }
  .tag.long { background: #fdebd0; color: #b9770e; }

  /* Footnote */
  .footnote { font-size: .82rem; color: var(--text-light); margin-top: 8px; font-style: italic; }

  /* Responsive */
  @media (max-width: 700px) {
    .chart-wrap.half { width: 100%; }
    .kpi-row { grid-template-columns: 1fr 1fr; }
    .topic-bar-label { width: 140px; font-size: .8rem; }
  }
  @media print {
    body { background: #fff; }
    .card, .kpi-card { box-shadow: none; border: 1px solid var(--border); }
  }
</style>
